    #[test]
    fn transform_graph_lowers_float_mod_to_math_fmod_residual_call() {
        let mut graph = FunctionGraph::new("float_mod");
        let lhs_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "lhs".into(),
                    ty: ValueType::Int,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let rhs_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "rhs".into(),
                    ty: ValueType::Float,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let result_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::BinOp {
                    op: "mod".into(),
                    lhs: lhs_var.clone(),
                    rhs: rhs_var.clone(),
                    result_ty: ValueType::Float,
                },
                true,
            )
            .unwrap();
        graph.set_return(graph.startblock, Some(result_var.clone()));

        FunctionGraph::set_concretetype_of_inline(&lhs_var, ConcreteType::Signed);
        FunctionGraph::set_concretetype_of_inline(&rhs_var, ConcreteType::Float);
        FunctionGraph::set_concretetype_of_inline(&result_var, ConcreteType::Float);

        let config = GraphTransformConfig::default();
        let transformed = Transformer::new(&config).transform(&graph);
        let ops = &transformed.graph.block(graph.startblock).operations;
        assert_eq!(ops.len(), 6, "Input + Input + cast + fnptr + call + Live");
        let cast_result = match &ops[2].kind {
            OpKind::UnaryOp {
                op,
                operand,
                result_ty,
            } => {
                assert_eq!(op, "cast_int_to_float");
                assert_eq!(*operand, lhs_var);
                assert_eq!(*result_ty, ValueType::Float);
                ops[2].result.clone().unwrap()
            }
            other => panic!("expected cast_int_to_float, got {other:?}"),
        };
        let expected_fnaddr =
            crate::call::symbolic_fnaddr_for_target(&CallTarget::function_path([
                "ll_math",
                "math_fmod",
            ]));
        assert!(
            matches!(&ops[3].kind, OpKind::ConstFnAddr { value, .. } if *value == expected_fnaddr)
        );
        match &ops[4].kind {
            OpKind::CallResidual {
                funcptr,
                descriptor,
                args_i,
                args_r,
                args_f,
                result_kind,
                indirect_targets,
            } => {
                assert!(matches!(funcptr, CallFuncPtr::Value(_)));
                assert_eq!(
                    descriptor.extra_info.extraeffect,
                    ExtraEffect::ElidableCanRaise
                );
                assert!(args_i.is_empty());
                assert!(args_r.is_empty());
                let cast_result_var = cast_result;
                assert_eq!(args_f, &vec![cast_result_var, rhs_var]);
                assert_eq!(*result_kind, 'f');
                assert!(indirect_targets.is_none());
            }
            other => panic!("expected CallResidual, got {other:?}"),
        }
        assert!(matches!(ops[5].kind, OpKind::Live));
    }

    #[test]
    fn transform_graph_lowers_int_str_to_jit_int_str_residual_call() {
        let mut graph = FunctionGraph::new("int_str");
        let n_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "n".into(),
                    ty: ValueType::Int,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let result_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::UnaryOp {
                    op: "str".into(),
                    operand: n_var.clone(),
                    result_ty: ValueType::Ref(None),
                },
                true,
            )
            .unwrap();
        graph.set_return(graph.startblock, Some(result_var.clone()));

        FunctionGraph::set_concretetype_of_inline(&n_var, ConcreteType::Signed);
        FunctionGraph::set_concretetype_of_inline(&result_var, ConcreteType::GcRef);

        let config = GraphTransformConfig::default();
        let transformed = Transformer::new(&config).transform(&graph);
        let ops = &transformed.graph.block(graph.startblock).operations;
        assert_eq!(ops.len(), 4, "Input + fnptr + call + Live");
        let expected_fnaddr =
            crate::call::symbolic_fnaddr_for_target(&CallTarget::function_path(["jit_int_str"]));
        assert!(
            matches!(&ops[1].kind, OpKind::ConstFnAddr { value, .. } if *value == expected_fnaddr)
        );
        match &ops[2].kind {
            OpKind::CallResidual {
                funcptr,
                descriptor,
                args_i,
                args_r,
                args_f,
                result_kind,
                indirect_targets,
            } => {
                assert!(matches!(funcptr, CallFuncPtr::Value(_)));
                assert_eq!(descriptor.extra_info.extraeffect, ExtraEffect::CanRaise);
                assert_eq!(args_i, &vec![n_var.clone()]);
                assert!(args_r.is_empty());
                assert!(args_f.is_empty());
                assert_eq!(*result_kind, 'r');
                assert!(indirect_targets.is_none());
            }
            other => panic!("expected CallResidual, got {other:?}"),
        }
        assert!(matches!(ops[3].kind, OpKind::Live));
    }

    /// `str(int)` over an Int operand, as one graph, for the two tests below.
    fn int_str_graph() -> (FunctionGraph, crate::flowspace::model::Variable) {
        let mut graph = FunctionGraph::new("int_str");
        let n_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "n".into(),
                    ty: ValueType::Int,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let result_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::UnaryOp {
                    op: "str".into(),
                    operand: n_var.clone(),
                    result_ty: ValueType::Ref(None),
                },
                true,
            )
            .unwrap();
        graph.set_return(graph.startblock, Some(result_var.clone()));
        FunctionGraph::set_concretetype_of_inline(&n_var, ConcreteType::Signed);
        FunctionGraph::set_concretetype_of_inline(&result_var, ConcreteType::GcRef);
        (graph, n_var)
    }

    /// The callee is the host's, not this layer's: a pipeline that names its
    /// own render helper gets a call to that one.
    ///
    /// Upstream needs no such setting because rtyping happens inside the
    /// interpreter's own translation, so `rstr.py ll_int2dec` is already the
    /// host's function. A Rust front end reads MIR that has no such helper in
    /// it, so the name has to come from the embedding pipeline.
    #[test]
    fn a_named_int_str_helper_is_the_call_target() {
        let (graph, _n_var) = int_str_graph();
        let config = GraphTransformConfig {
            int_str_helper: "grain_render_int".to_string(),
            ..Default::default()
        };
        let transformed = Transformer::new(&config).transform(&graph);
        let ops = &transformed.graph.block(graph.startblock).operations;
        assert_eq!(ops.len(), 4, "Input + fnptr + call + Live");
        let expected = crate::call::symbolic_fnaddr_for_target(&CallTarget::function_path([
            "grain_render_int",
        ]));
        assert!(
            matches!(&ops[1].kind, OpKind::ConstFnAddr { value, .. } if *value == expected),
            "the fnptr names the configured helper, not this layer's default",
        );
    }

    /// An unnamed helper emits the host-refusal abort before the original op.
    #[test]
    fn an_unnamed_int_str_helper_aborts_before_the_original_op() {
        let (graph, _n_var) = int_str_graph();
        let config = GraphTransformConfig {
            int_str_helper: String::new(),
            ..Default::default()
        };
        let transformed = Transformer::new(&config).transform(&graph);
        let ops = &transformed.graph.block(graph.startblock).operations;
        assert!(
            !ops.iter()
                .any(|op| matches!(op.kind, OpKind::CallResidual { .. })),
            "no helper is named, so nothing is called: {ops:?}",
        );
        assert!(
            matches!(
                &ops[1].kind,
                OpKind::Abort {
                    kind: crate::model::UnknownKind::UnsupportedExpr {
                        variant: crate::model::UnsupportedExprKind::HostHelperRefused,
                    },
                }
            ),
            "the host refusal must be explicit: {ops:?}",
        );
        assert!(
            matches!(&ops[2].kind, OpKind::UnaryOp { op: name, .. } if name == "str"),
            "the original op stays residual after the abort: {ops:?}",
        );
    }

    /// `s1 + s2` over two Ref operands, as one graph, for the two tests below.
    fn str_concat_graph() -> FunctionGraph {
        let mut graph = FunctionGraph::new("str_concat");
        let lhs = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "lhs".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let rhs = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "rhs".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let result = graph
            .push_op_var(
                graph.startblock,
                OpKind::BinOp {
                    op: "add".into(),
                    lhs: lhs.clone(),
                    rhs: rhs.clone(),
                    result_ty: ValueType::Ref(None),
                },
                true,
            )
            .unwrap();
        graph.set_return(graph.startblock, Some(result.clone()));
        FunctionGraph::set_concretetype_of_inline(&lhs, ConcreteType::GcRef);
        FunctionGraph::set_concretetype_of_inline(&rhs, ConcreteType::GcRef);
        FunctionGraph::set_concretetype_of_inline(&result, ConcreteType::GcRef);
        graph
    }

