    /// `jtransform.py` — `rewrite_op_int_add_ovf` (aliased to
    /// `rewrite_op_int_mul_ovf`) and `rewrite_op_int_sub_ovf` both return
    /// `[SpaceOperation('-live-', [], None), op]`.  `flatten` pops the
    /// overflow-checked op back off the emitted line and re-spells it as
    /// `int_*_jump_if_ovf`, a guard that resumes at this point, so the
    /// marker must be established here rather than inherited from whatever
    /// operation happens to precede it.
    #[test]
    fn transform_graph_leads_overflow_checked_binops_with_live() {
        for opname in ["add_ovf", "sub_ovf", "mul_ovf"] {
            let mut graph = FunctionGraph::new("ovf");
            let entry = graph.startblock;
            let lhs = graph.push_op_var(entry, OpKind::ConstInt(1), true).unwrap();
            let rhs = graph.push_op_var(entry, OpKind::ConstInt(2), true).unwrap();
            graph.push_op_var(
                entry,
                OpKind::BinOp {
                    op: opname.into(),
                    lhs,
                    rhs,
                    result_ty: crate::model::ValueType::Int,
                },
                true,
            );

            let result = transform_graph(&graph, &GraphTransformConfig::default());
            let ops = &result.graph.block(entry).operations;
            let ovf_idx = ops
                .iter()
                .position(|o| matches!(&o.kind, OpKind::BinOp { op, .. } if op == opname))
                .unwrap_or_else(|| panic!("{opname} did not survive the rewrite: {ops:?}"));
            assert!(
                ovf_idx > 0 && matches!(ops[ovf_idx - 1].kind, OpKind::Live),
                "{opname} must be led by -live-, got {ops:?}"
            );
        }
    }

    /// `jtransform.py:1748-1755` — `jit.not_in_trace`'s registered spec is
    /// `"jit.not_in_trace()"` (`rlib/jit.py`), an empty argtuple, so the
    /// decoded arg list comes back empty.  Upstream ignores it ("use the
    /// original 'op.args'") and the residual call keeps the arguments the
    /// call site passes.
    #[test]
    fn not_in_trace_residual_call_keeps_the_original_arguments() {
        let path = crate::parse::CallPath::from_segments(["helper", "trace_hook"]);
        let target = CallTarget::function_path(["helper", "trace_hook"]);

        let mut cc = crate::call::CallControl::new();
        cc.mark_oopspec(path.clone(), "jit.not_in_trace()".to_string());
        // A non-empty argname list is what routes the decode through
        // `parse_oopspec` + `normalize_opargs` rather than the positional
        // pass-through fallback.
        cc.mark_oopspec_argnames(path, vec!["x".into(), "y".into()]);

        let mut graph = FunctionGraph::new("caller");
        let x = graph.alloc_value_var();
        let y = graph.alloc_value_var();
        FunctionGraph::set_concretetype_of_inline(&x, ConcreteType::Signed);
        FunctionGraph::set_concretetype_of_inline(&y, ConcreteType::Signed);
        let startblock = graph.startblock;
        graph.push_op_var(
            startblock,
            OpKind::Call {
                target,
                args: crate::model::call_args(vec![x.clone(), y.clone()]),
                result_ty: ValueType::Void,
            },
            false,
        );

        let config = GraphTransformConfig::default();
        let transformed = Transformer::new(&config)
            .with_callcontrol(&mut cc)
            .transform(&graph);

        let args_i = transformed
            .graph
            .block(startblock)
            .operations
            .iter()
            .find_map(|op| match &op.kind {
                OpKind::CallResidual { args_i, .. } => Some(args_i.clone()),
                _ => None,
            })
            .expect("not_in_trace must lower to a residual call");
        assert_eq!(args_i, vec![x, y]);
    }

    /// `rlib/jit.py conditional_call` harvested as
    /// `oopspec("jit.conditional_call")`. Argument order is
    /// `(condition, funcptr, args)`, matching `_rewrite_op_cond_call`.
    #[test]
    fn jit_conditional_call_rlib_helper_rewrites_to_conditional_call() {
        let helper_path =
            crate::parse::CallPath::from_segments(["majit_rlib", "jit", "conditional_call1"]);
        let helper_target = CallTarget::function_path(["majit_rlib", "jit", "conditional_call1"]);
        let callee_target = CallTarget::function_path([
            crate::model::FN_CONST_HEAD,
            "pyre_object",
            "listobject",
            "ll_list_int_resize_hint_really",
        ]);

        let mut cc = crate::call::CallControl::new();
        cc.mark_oopspec(helper_path, "jit.conditional_call".to_string());

        let mut graph = FunctionGraph::new("resize_ge");
        let cond = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let arg = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        FunctionGraph::set_concretetype_of_inline(&cond, ConcreteType::Signed);
        FunctionGraph::set_concretetype_of_inline(&arg, ConcreteType::GcRef);
        graph.push_inputarg_var(graph.startblock, cond.clone());
        graph.push_inputarg_var(graph.startblock, arg.clone());

        let startblock = graph.startblock;
        let func_var = graph
            .push_op_var(
                startblock,
                OpKind::Call {
                    target: callee_target,
                    args: crate::model::call_args(vec![]),
                    result_ty: ValueType::Int,
                },
                true,
            )
            .unwrap();
        graph.push_op_var(
            startblock,
            OpKind::Call {
                target: helper_target,
                args: crate::model::call_args(vec![cond.clone(), func_var, arg.clone()]),
                result_ty: ValueType::Void,
            },
            false,
        );

        let config = GraphTransformConfig::default();
        let transformed = Transformer::new(&config)
            .with_callcontrol(&mut cc)
            .transform(&graph);

        let found = transformed
            .graph
            .block(startblock)
            .operations
            .iter()
            .find_map(|op| match &op.kind {
                OpKind::ConditionalCall {
                    condition,
                    funcptr,
                    args_r,
                    ..
                } => Some((condition.clone(), funcptr.clone(), args_r.clone())),
                _ => None,
            })
            .expect("jit.conditional_call must lower to ConditionalCall");
        assert_eq!(found.0, cond);
        match found.1 {
            CallTarget::FunctionPath { segments, .. } => {
                assert_eq!(
                    segments,
                    [
                        "pyre_object",
                        "listobject",
                        "ll_list_int_resize_hint_really"
                    ]
                );
            }
            other => panic!("expected stripped function path, got {other:?}"),
        }
        assert_eq!(found.2, vec![arg]);
    }

    /// `rlib/jit.py conditional_call_elidable` harvested as
    /// `oopspec("jit.conditional_call_value")`. Argument order is
    /// `(value, funcptr, args)`, matching `_rewrite_op_cond_call`.
    #[test]
    fn jit_conditional_call_value_rlib_helper_rewrites_to_conditional_call_value() {
        let helper_path = crate::parse::CallPath::from_segments([
            "majit_rlib",
            "jit",
            "conditional_call_elidable1",
        ]);
        let helper_target =
            CallTarget::function_path(["majit_rlib", "jit", "conditional_call_elidable1"]);
        let callee_target = CallTarget::function_path([
            crate::model::FN_CONST_HEAD,
            "pyre_object",
            "unicodeobject",
            "w_str_compute_index_storage",
        ]);

        let mut cc = crate::call::CallControl::new();
        cc.mark_oopspec(helper_path, "jit.conditional_call_value".to_string());

        let mut graph = FunctionGraph::new("get_index_storage");
        let value = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let arg = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        FunctionGraph::set_concretetype_of_inline(&value, ConcreteType::GcRef);
        FunctionGraph::set_concretetype_of_inline(&arg, ConcreteType::GcRef);
        graph.push_inputarg_var(graph.startblock, value.clone());
        graph.push_inputarg_var(graph.startblock, arg.clone());

        let startblock = graph.startblock;
        let func_var = graph
            .push_op_var(
                startblock,
                OpKind::Call {
                    target: callee_target,
                    args: crate::model::call_args(vec![]),
                    result_ty: ValueType::Int,
                },
                true,
            )
            .unwrap();
        let result_var = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        graph.push_op_var(
            startblock,
            OpKind::Call {
                target: helper_target,
                args: crate::model::call_args(vec![value.clone(), func_var, arg.clone()]),
                result_ty: ValueType::Ref(None),
            },
            false,
        );
        graph
            .block_mut(startblock)
            .operations
            .last_mut()
            .unwrap()
            .result = Some(result_var);

        let config = GraphTransformConfig::default();
        let transformed = Transformer::new(&config)
            .with_callcontrol(&mut cc)
            .transform(&graph);

        let found = transformed
            .graph
            .block(startblock)
            .operations
            .iter()
            .find_map(|op| match &op.kind {
                OpKind::ConditionalCallValue {
                    value: v,
                    funcptr,
                    args_r,
                    result_kind,
                    ..
                } => Some((v.clone(), funcptr.clone(), args_r.clone(), *result_kind)),
                _ => None,
            })
            .expect("jit.conditional_call_value must lower to ConditionalCallValue");
        assert_eq!(found.0, value);
        match found.1 {
            CallTarget::FunctionPath { segments, .. } => {
                assert_eq!(
                    segments,
                    [
                        "pyre_object",
                        "unicodeobject",
                        "w_str_compute_index_storage"
                    ]
                );
            }
            other => panic!("expected stripped function path, got {other:?}"),
        }
        assert_eq!(found.2, vec![arg]);
        assert_eq!(found.3, 'r');
    }

    /// `rpython/jit/codewriter/jtransform.py rewrite_op_hint`
    /// `promote=True` branch: emits `[-live-, <kind>_guard_value(x),
    /// None]` where the `None` sentinel aliases the result back to the
    /// input arg.  In pyre's `RewriteResult` model the alias is applied
    /// by `optimize_block` from `self.aliases.insert(result, base)` and
    /// the two emitted ops show up at the call site as
    /// `[OpKind::Live, OpKind::GuardValue { kind_char }]`.
    #[test]
    fn transform_graph_rewrites_hint_promote() {
        let mut graph = FunctionGraph::new("demo");
        let v_var = graph.alloc_value_var();
        let promoted_var = graph.alloc_value_var();
        let consumed_var = graph.alloc_value_var();
        graph.push_inputarg_var(graph.startblock, v_var.clone());
        // `hint_promote(v)` — mirrors `rlib/jit.py promote(x)` after
        // lowering to the operator-level helper name.
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::function_path(["hint_promote"]),
                args: crate::model::call_args(vec![v_var.clone()]),
                result_ty: ValueType::Ref(None),
            },
            false,
        );
        graph
            .block_mut(graph.startblock)
            .operations
            .last_mut()
            .unwrap()
            .result = Some(promoted_var.clone());
        // A downstream op that names the promote result so we can
        // observe that `optimize_block` aliased it back to `v`.
        graph.push_op_var(
            graph.startblock,
            OpKind::FieldRead {
                base: promoted_var,
                field: crate::model::FieldDescriptor::new("payload", Some("Box".into())),
                ty: ValueType::Int,
                pure: false,
            },
            false,
        );
        graph
            .block_mut(graph.startblock)
            .operations
            .last_mut()
            .unwrap()
            .result = Some(consumed_var);
        graph.set_return(graph.startblock, None);

        let result = transform_graph(&graph, &GraphTransformConfig::default());
        let ops = &result.graph.block(graph.startblock).operations;
        // Expected post-rewrite shape: [Live, GuardValue, FieldRead].
        assert_eq!(ops.len(), 3, "got {ops:?}");
        assert!(matches!(ops[0].kind, OpKind::Live));
        match &ops[1].kind {
            OpKind::GuardValue {
                value, kind_char, ..
            } => {
                assert_eq!(value, &v_var, "guard target must remain the input arg");
                assert_eq!(*kind_char, 'r', "default kind without type-state");
            }
            other => panic!("expected GuardValue, got {other:?}"),
        }
        // `None` sentinel parity: the downstream FieldRead, which named
        // the `promoted` result, must have its base resolved back to `v`.
        match &ops[2].kind {
            OpKind::FieldRead { base, .. } => {
                assert_eq!(base, &v_var, "promote result must alias back to input arg");
            }
            other => panic!("expected FieldRead, got {other:?}"),
        }
    }

    /// `jtransform.py:608` voidness guard — `if hints.get('promote')
    /// and op.args[0].concretetype is not lltype.Void`.  Pyre falls
    /// through (Keep) when `value_kind(arg) == 'v'`.
    #[test]
    fn transform_graph_keeps_hint_promote_on_void_arg() {
        let mut graph = FunctionGraph::new("demo");
        let v_var = graph.alloc_value_var();
        graph.push_inputarg_var(graph.startblock, v_var.clone());
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::function_path(["hint_promote"]),
                args: crate::model::call_args(vec![v_var.clone()]),
                result_ty: ValueType::Void,
            },
            false,
        );
        graph.set_return(graph.startblock, None);

        let config = GraphTransformConfig::default();
        // Mark `v` as void-kind on its backing Variable before
        // rewriting (mirrors RPython's `v.concretetype = lltype.Void`).
        FunctionGraph::set_concretetype_of_inline(
            &v_var,
            crate::codewriter::type_state::ConcreteType::Void,
        );
        let mut transformer = Transformer::new(&config);
        // Direct call to rewrite_operation — without setting up the
        // optimize_block plumbing — verifies the Keep result for the
        // void-kind branch in isolation.
        let op = graph
            .block(graph.startblock)
            .operations
            .last()
            .unwrap()
            .clone();
        assert!(matches!(
            transformer.rewrite_operation(&op, "demo", &mut graph),
            RewriteResult::Keep
        ));
    }

    /// RPython `rpython/jit/codewriter/jtransform.py:895-903` — a
    /// quasi-immutable field read lowers to
    /// `[-live-, record_quasiimmut_field(v, descr, descr1), getfield_*_pure]`.
    /// Covers Issue 5.
    #[test]
    fn getfield_rewrite_emits_record_quasiimmut_for_quasi_immut() {
        use crate::call::CallControl;
        use crate::model::{FieldDescriptor, ImmutableRank};

        let mut cc = CallControl::new();
        cc.immutable_fields_by_struct.insert(
            "Cell".to_string(),
            vec![("value".to_string(), ImmutableRank::QuasiImmutable)],
        );

        let mut graph = FunctionGraph::new("read_cell");
        let base_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "cell".to_string(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        graph.push_op_var(
            graph.startblock,
            OpKind::FieldRead {
                base: base_var,
                field: FieldDescriptor::new("value", Some("Cell".to_string())),
                ty: ValueType::Int,
                pure: false,
            },
            true,
        );
        graph.set_return(graph.startblock, None);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);
        let ops: Vec<&OpKind> = result
            .graph
            .block(graph.startblock)
            .operations
            .iter()
            .map(|o| &o.kind)
            .collect();

        // Expect the triple [Live, RecordQuasiImmutField, FieldRead] in
        // order, preceded by the Input op.
        let live_idx = ops
            .iter()
            .position(|k| matches!(k, OpKind::Live))
            .expect("Live marker present");
        assert!(matches!(
            ops[live_idx + 1],
            OpKind::RecordQuasiImmutField {
                field, mutate_field, ..
            } if field.name == "value"
                && mutate_field.name == "mutate_value"
                && mutate_field.owner_root.as_deref() == Some("Cell")
        ));
        assert!(matches!(
            ops[live_idx + 2],
            OpKind::FieldRead {
                field, pure: true, ..
            } if field.name == "value"
        ));
    }

    /// A plain-immutable field read lowers directly to a pure read, without
    /// the quasi-immutable bookkeeping pair.  Mirrors the `pure` /
    /// non-`pure` fork at `jtransform.py:867-878`.
    #[test]
    fn getfield_rewrite_preserves_plain_immutable_read() {
        use crate::call::CallControl;
        use crate::model::{FieldDescriptor, ImmutableRank};

        let mut cc = CallControl::new();
        cc.immutable_fields_by_struct.insert(
            "Point".to_string(),
            vec![("x".to_string(), ImmutableRank::Immutable)],
        );

        let mut graph = FunctionGraph::new("read_x");
        let base_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "p".to_string(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        graph.push_op_var(
            graph.startblock,
            OpKind::FieldRead {
                base: base_var,
                field: FieldDescriptor::new("x", Some("Point".to_string())),
                ty: ValueType::Int,
                pure: false,
            },
            true,
        );
        graph.set_return(graph.startblock, None);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);
        let ops = &result.graph.block(graph.startblock).operations;

        assert!(
            !ops.iter()
                .any(|o| matches!(o.kind, OpKind::RecordQuasiImmutField { .. })),
            "plain immutable must not emit record_quasiimmut_field"
        );
        assert!(
            ops.iter().any(|o| matches!(
                &o.kind,
                OpKind::FieldRead {
                    field, pure: true, ..
                } if field.name == "x"
            )),
            "FieldRead for x should become a pure read"
        );
    }

    /// `rewrite_op_getarrayitem`: a base loaded from a `name[*]` field
    /// (`IR_IMMUTABLE_ARRAY`) makes the element read `getarrayitem_gc_*_pure`.
    #[test]
    fn getarrayitem_from_star_field_is_pure() {
        assert_star_field_item_read_is_pure(false);
    }

    /// `w_tuple_getitem_known` reads `items_block_items_base(t.wrappeditems)[i]`:
    /// the accessor returns its block, so the read keeps the `[*]` origin.
    #[test]
    fn getarrayitem_through_items_base_accessor_of_star_field_is_pure() {
        assert_star_field_item_read_is_pure(true);
    }

    fn assert_star_field_item_read_is_pure(through_accessor: bool) {
        use crate::call::CallControl;
        use crate::model::{FieldDescriptor, ImmutableRank};

        let mut cc = CallControl::new();
        cc.immutable_fields_by_struct.insert(
            "Holder".to_string(),
            vec![("payload".to_string(), ImmutableRank::ImmutableArray)],
        );

        let mut graph = FunctionGraph::new("read_star_item");
        let holder = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "holder".to_string(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let index = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "i".to_string(),
                    ty: ValueType::Int,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let arr = graph
            .push_op_var(
                graph.startblock,
                OpKind::FieldRead {
                    base: holder,
                    field: FieldDescriptor::new("payload", Some("Holder".to_string())),
                    ty: ValueType::Ref(None),
                    pure: false,
                },
                true,
            )
            .unwrap();
        let base = if through_accessor {
            graph
                .push_op_var(
                    graph.startblock,
                    OpKind::Call {
                        target: CallTarget::function_path([
                            "pyre_object",
                            "object_array",
                            "items_block_items_base",
                        ]),
                        args: vec![crate::model::LinkArg::from(arr)],
                        result_ty: ValueType::Ref(None),
                    },
                    true,
                )
                .unwrap()
        } else {
            arr
        };
        graph.push_op_var(
            graph.startblock,
            OpKind::ArrayRead {
                base,
                index,
                item_ty: ValueType::Ref(None),
                array_type_id: None,
                nolength: false,
                pure: false,
            },
            true,
        );
        graph.set_return(graph.startblock, None);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);
        assert!(
            result
                .graph
                .block(graph.startblock)
                .operations
                .iter()
                .any(|o| matches!(&o.kind, OpKind::ArrayRead { pure: true, .. })),
            "ArrayRead from a [*] field must be rewritten pure"
        );
    }

