    /// RPython `Transformer.rewrite_op_cast_opaque_ptr` aliases the
    /// low-level operation, while `rewrite_op_cast_ptr_to_int` preserves a
    /// GC cast. A subsequent int-to-pointer cast must remain explicit.
    #[test]
    fn pointer_casts_preserve_integer_roundtrip() {
        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config);
        let mut graph = FunctionGraph::new("pointer_casts");
        let ptr = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let as_int = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let as_ptr = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        for (name, operand, result, result_ty) in [
            (
                "cast_ptr_to_int",
                ptr.clone(),
                as_int.clone(),
                ValueType::Int,
            ),
            (
                "cast_int_to_ptr",
                as_int,
                as_ptr.clone(),
                ValueType::Ref(None),
            ),
        ] {
            let op = SpaceOperation {
                result: Some(result),
                kind: OpKind::UnaryOp {
                    op: name.into(),
                    operand,
                    result_ty,
                },
            };
            assert!(
                matches!(
                    transformer.rewrite_operation(&op, "pointer_casts", &mut graph),
                    RewriteResult::Keep
                ),
                "{name} must remain explicit"
            );
        }
        let op = SpaceOperation {
            result: Some(as_ptr),
            kind: OpKind::UnaryOp {
                op: "cast_opaque_ptr".into(),
                operand: ptr.clone(),
                result_ty: ValueType::Ref(None),
            },
        };
        match transformer.rewrite_operation(&op, "pointer_casts", &mut graph) {
            RewriteResult::Identity(alias) => assert_eq!(alias, ptr),
            _ => panic!("expected the explicit opaque cast to alias its operand"),
        }
    }

    /// `longlong2float` rewrites to `convert_longlong_bytes_to_float` and
    /// `float2longlong` rewrites to `convert_float_bytes_to_longlong`.
    #[test]
    fn float_longlong_calls_rewrite_to_convert_llop() {
        let cases = [
            (
                "longlong2float",
                "longlong2float_call",
                ConcreteType::Signed,
                ConcreteType::Float,
                ["longlong2float", "longlong2float"],
                ValueType::Float,
                "convert_longlong_bytes_to_float",
                ValueType::Float,
            ),
            (
                "float2longlong",
                "float2longlong_call",
                ConcreteType::Float,
                ConcreteType::Signed,
                ["longlong2float", "float2longlong"],
                ValueType::Int,
                "convert_float_bytes_to_longlong",
                ValueType::Int,
            ),
        ];
        for (name, graph_name, arg_ty, result_concrete, path, result_ty, opname, unary_ty) in cases
        {
            let config = GraphTransformConfig::default();
            let mut transformer = Transformer::new(&config);
            let mut graph = FunctionGraph::new(graph_name);
            let arg = graph.alloc_value_var_with_type(arg_ty);
            let result_var = graph.alloc_value_var_with_type(result_concrete);
            let target = CallTarget::function_path(path);
            let op = SpaceOperation {
                result: Some(result_var.clone()),
                kind: OpKind::Call {
                    target: target.clone(),
                    args: crate::model::call_args(vec![arg.clone()]),
                    result_ty: result_ty.clone(),
                },
            };
            let rewritten = transformer.rewrite_op_direct_call(
                &op,
                &target,
                std::slice::from_ref(&arg),
                &result_ty,
                graph_name,
                &mut graph,
            );
            match rewritten {
                RewriteResult::Replace(ops) => {
                    assert_eq!(ops.len(), 1, "case {name}");
                    match &ops[0].kind {
                        OpKind::UnaryOp {
                            op,
                            operand,
                            result_ty,
                        } => {
                            assert_eq!(op, opname, "case {name}");
                            assert_eq!(operand, &arg, "case {name}");
                            assert_eq!(*result_ty, unary_ty, "case {name}");
                        }
                        other => panic!("case {name}: expected {opname}, got {other:?}"),
                    }
                    assert_eq!(ops[0].result.as_ref(), Some(&result_var), "case {name}");
                }
                _ => panic!("case {name}: expected Replace({opname})"),
            }
        }
    }

    /// A leftover `i64::checked_add` Call becomes `add_ovf` plus `-live-`,
    /// matching `rewrite_op_int_add_ovf`.
    #[test]
    fn checked_add_call_rewrites_to_add_ovf() {
        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config);
        let mut graph = FunctionGraph::new("checked_add_call");
        let lhs = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let rhs = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let result_var = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let target = CallTarget::function_path(["core", "num", "<Impl>", "checked_add"]);
        let result_ty = ValueType::Int;
        let op = SpaceOperation {
            result: Some(result_var.clone()),
            kind: OpKind::Call {
                target: target.clone(),
                args: crate::model::call_args(vec![lhs.clone(), rhs.clone()]),
                result_ty: result_ty.clone(),
            },
        };
        let rewritten = transformer.rewrite_op_direct_call(
            &op,
            &target,
            &[lhs.clone(), rhs.clone()],
            &result_ty,
            "checked_add_call",
            &mut graph,
        );
        match rewritten {
            RewriteResult::Replace(ops) => {
                assert_eq!(ops.len(), 2);
                assert!(matches!(ops[0].kind, OpKind::Live));
                match &ops[1].kind {
                    OpKind::BinOp { op, result_ty, .. } => {
                        assert_eq!(op, "add_ovf");
                        assert_eq!(*result_ty, ValueType::Int);
                    }
                    other => panic!("expected add_ovf, got {other:?}"),
                }
            }
            _ => panic!("expected Replace(add_ovf)"),
        }
    }

    /// Grain packs a `Position` into an i64 as `position_from_bits`. A
    /// substring `from_bits` match would rewrite that call to
    /// `convert_longlong_bytes_to_float` and make the caller
    /// `float_return` a Position. The leaf is the method name itself.
    #[test]
    fn position_from_bits_is_not_a_float_bitcast() {
        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config);
        let mut graph = FunctionGraph::new("position_from_bits_call");
        let bits = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let result_var = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let target =
            CallTarget::function_path(["rhai", "grain", "vm", "jit", "position_from_bits"]);
        let result_ty = ValueType::Ref(None);
        let op = SpaceOperation {
            result: Some(result_var),
            kind: OpKind::Call {
                target: target.clone(),
                args: crate::model::call_args(vec![bits.clone()]),
                result_ty: result_ty.clone(),
            },
        };
        let rewritten = transformer.rewrite_op_direct_call(
            &op,
            &target,
            std::slice::from_ref(&bits),
            &result_ty,
            "position_from_bits_call",
            &mut graph,
        );
        let folded_to_bitcast = match &rewritten {
            RewriteResult::Replace(ops) => ops.iter().any(|op| {
                matches!(
                    &op.kind,
                    OpKind::UnaryOp { op, .. }
                        if op == "convert_longlong_bytes_to_float"
                            || op == "convert_float_bytes_to_longlong"
                )
            }),
            _ => false,
        };
        assert!(
            !folded_to_bitcast,
            "position_from_bits must not fold to a float bitcast"
        );
    }

    /// `Transformer.rewrite_op_direct_call` dispatches real calls through
    /// CallControl; a function's leaf name does not make it a low-level cast.
