    /// The rtyper's specialized `ll_arraycopy(source, dest, length)` must
    /// still emit the five-argument `jit_ll_arraycopy` ABI, with the two
    /// missing starts rewritten as constant zero.
    #[test]
    fn list_ll_arraycopy_three_arg_expands_to_five_arg_abi() {
        use crate::call::CallControl;
        use crate::translator::rtyper::lltypesystem::lltype::{
            Array, LowLevelType, Ptr, PtrTarget,
        };
        use crate::translator::rtyper::rtyper::variable_with_lltype;

        let mut cc = CallControl::new();
        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let mut graph = FunctionGraph::new("arraycopy");
        let array_ty = LowLevelType::Ptr(Box::new(Ptr {
            TO: PtrTarget::Array(Array::gc(LowLevelType::Signed)),
        }));
        let args = vec![
            variable_with_lltype("source", array_ty.clone()),
            variable_with_lltype("dest", array_ty),
            variable_with_lltype("length", LowLevelType::Signed),
        ];
        let op = SpaceOperation {
            result: None,
            kind: OpKind::Call {
                target: CallTarget::function_path(["ll_arraycopy"]),
                args: crate::model::call_args(args.clone()),
                result_ty: ValueType::Void,
            },
        };
        let rewritten = transformer
            ._handle_list_call("list.ll_arraycopy", &op, &args, &mut graph, "arraycopy")
            .expect("list.ll_arraycopy must be handled");
        let RewriteResult::Replace(ops) = rewritten else {
            panic!("expected Replace");
        };
        let zeros: Vec<_> = ops
            .iter()
            .filter(|op| matches!(op.kind, OpKind::ConstInt(0)))
            .collect();
        assert_eq!(
            zeros.len(),
            2,
            "specialized call inserts two start=0 consts"
        );
        let residual = ops.iter().find_map(|op| match &op.kind {
            OpKind::CallResidual {
                args_i,
                args_r,
                args_f,
                result_kind,
                ..
            } => Some((args_i, args_r, args_f, result_kind)),
            _ => None,
        });
        let Some((args_i, args_r, args_f, result_kind)) = residual else {
            panic!("expected a CallResidual, got {ops:?}");
        };
        assert_eq!(args_r, &args[0..2], "source then dest");
        let source_start = zeros[0]
            .result
            .as_ref()
            .expect("source_start const has a result");
        let dest_start = zeros[1]
            .result
            .as_ref()
            .expect("dest_start const has a result");
        assert_eq!(
            args_i,
            &[source_start.clone(), dest_start.clone(), args[2].clone()],
            "starts then length"
        );
        assert!(args_f.is_empty());
        assert_eq!(*result_kind, 'v');
        let callinfo = &transformer
            .callcontrol
            .as_deref()
            .unwrap()
            .callinfocollection;
        assert!(callinfo.has_oopspec(OopSpecIndex::Arraycopy));
        let (_, fnaddr) = callinfo.callinfo_for_oopspec(OopSpecIndex::Arraycopy);
        assert_eq!(callinfo.func_name(fnaddr), Some("jit_ll_arraycopy"));
    }

    /// Other `rgc.*` spellings are not ported and fall through to the
    /// residual-call path.
    #[test]
    fn rgc_unported_spellings_fall_through() {
        use crate::call::CallControl;
        use crate::translator::rtyper::lltypesystem::lltype::LowLevelType;
        use crate::translator::rtyper::rtyper::variable_with_lltype;

        let mut cc = CallControl::new();
        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let mut graph = FunctionGraph::new("rgc_other");
        let args = vec![variable_with_lltype("x", LowLevelType::Signed)];
        let op = SpaceOperation {
            result: None,
            kind: OpKind::Live,
        };
        assert!(
            transformer
                ._handle_rgc_call(
                    "rgc.something_else",
                    &op,
                    &CallTarget::function_path(["something_else"]),
                    &args,
                    &ValueType::Void,
                    "rgc_other",
                    &mut graph,
                )
                .is_none()
        );
    }

    //
    // RPython upstream: `jtransform.py handle_regular_indirect_call handle_regular_indirect_
    // call` emits `[-live-, int_guard_value, residual_call +
    // IndirectCallTargets, -live-]`; `assembler.py:208-209` collects
    // the candidate jitcodes into `indirectcalltargets`.  These two
    // tests anchor the RPython-orthodox post-jtransform shape so any
    // future change to `lower_indirect_calls` / `Transformer::transform`
    // surfaces here rather than reaching the assembler with a wrong
    // op sequence.

    /// Build an impl-method graph with a single `Input { ty: Ref }`
    /// representing the receiver `self` — mirrors the one-arg signature
    /// `fn run(&self)` that `FunctionReprBase.call` feeds into
    /// `indirect_call(funcptr, self, c_graphs)` (`rpbc.py`).
    fn build_handler_run_impl_graph(name: &str) -> FunctionGraph {
        let mut graph = FunctionGraph::new(name);
        graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "self".to_string(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        graph.set_return(graph.startblock, None);
        graph
    }

    /// An indirect family whose first parameter is void
    /// (`map_by_fn_name_token::call`'s ZST receiver) and whose caller
    /// still passes that slot as a ref. The calldescr and `args_r`
    /// both drop it, matching the callee's non-void inputs.
    #[test]
    fn indirect_family_drops_void_receiver_with_the_callee() {
        use crate::call::CallControl;

        let mut callee = FunctionGraph::new("Token::call");
        callee
            .push_op_var(
                callee.startblock,
                OpKind::Input {
                    name: "self".into(),
                    ty: ValueType::Void,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        callee
            .push_op_var(
                callee.startblock,
                OpKind::Input {
                    name: "a".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        callee
            .push_op_var(
                callee.startblock,
                OpKind::Input {
                    name: "b".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        callee.set_return(callee.startblock, None);

        let mut cc = CallControl::new();
        cc.register_trait_method("call", Some("MapByName"), "Token", callee);
        let family = cc.all_impls_for_indirect("MapByName", "call");
        assert_eq!(family.len(), 1);

        let mut graph = FunctionGraph::new("caller");
        let bb = graph.startblock;
        let funcptr = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let args: Vec<_> = (0..3)
            .map(|_| graph.alloc_value_var_with_type(ConcreteType::GcRef))
            .collect();
        graph.block_mut(bb).operations.push(SpaceOperation {
            result: None,
            kind: OpKind::IndirectCall {
                funcptr,
                args,
                graphs: Some(family),
                family_key: Some(("MapByName".into(), "call".into())),
                result_ty: ValueType::Void,
            },
        });
        graph.set_return(bb, None);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);
        let args_r_len = result
            .graph
            .block(bb)
            .operations
            .iter()
            .find_map(|op| match &op.kind {
                OpKind::CallResidual { args_r, .. } => Some(args_r.len()),
                _ => None,
            })
            .expect("indirect call lowered to a residual");
        assert_eq!(args_r_len, 2);
    }

    /// `rewrite_op_setfield` drops a void value (`RESULT is lltype.Void`),
    /// so a unit payload never reaches the assembler uncolored.
    #[test]
    fn setfield_of_void_unit_payload_is_dropped() {
        let mut graph = FunctionGraph::new("apply_assign_fast");
        let bb = graph.startblock;
        let base = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let unit = graph.alloc_value_var_with_type(ConcreteType::Void);
        graph.block_mut(bb).operations.push(SpaceOperation {
            result: None,
            kind: OpKind::FieldWrite {
                base,
                field: crate::model::FieldDescriptor::new("payload", None),
                value: LinkArg::Value(unit),
                ty: ValueType::Ref(None),
            },
        });
        graph.set_return(bb, None);
        let transformed = Transformer::new(&GraphTransformConfig::default()).transform(&graph);
        assert!(transformed.graph.blocks.iter().all(|block| {
            block
                .operations
                .iter()
                .all(|op| !matches!(op.kind, OpKind::FieldWrite { .. }))
        }));
    }

    /// `rewrite_op_getfield` drops a void result (`RESULT is lltype.Void`),
    /// so a unit field never reaches the assembler uncolored.
    #[test]
    fn getfield_of_void_result_is_dropped() {
        let mut graph = FunctionGraph::new("void_getfield");
        let bb = graph.startblock;
        let base = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let result = graph.alloc_value_var_with_type(ConcreteType::Void);
        graph.block_mut(bb).operations.push(SpaceOperation {
            result: Some(result),
            kind: OpKind::FieldRead {
                base,
                field: crate::model::FieldDescriptor::new("payload", None),
                ty: ValueType::Void,
                pure: true,
            },
        });
        graph.set_return(bb, None);
        let transformed = Transformer::new(&GraphTransformConfig::default()).transform(&graph);
        assert!(transformed.graph.blocks.iter().all(|block| {
            block
                .operations
                .iter()
                .all(|op| !matches!(op.kind, OpKind::FieldRead { .. }))
        }));
    }

    /// Build a graph that calls `receiver.run()` on a `dyn Handler`
    /// receiver with two registered impls, run the rtyper-equivalent
    /// `lower_indirect_calls` pass and then `Transformer::transform`,
    /// and assert the post-jtransform sequence is exactly
    /// `[VtableMethodPtr, Live, GuardValue{kind='i'},
    ///   CallResidual{funcptr=Value(_), indirect_targets=Some}, Live]`.
    /// RPython `jtransform.py + 538-553` orthodox port parity.
    #[test]
    fn lower_indirect_call_op_emit_order() {
        use crate::call::CallControl;
        use crate::translator::rtyper::legacy_annotator::annotate;
        use crate::translator::rtyper::legacy_resolve::resolve_types;
        use crate::translator::rtyper::rpbc::lower_indirect_calls;

        let mut cc = CallControl::new();
        cc.register_trait_method(
            "run",
            Some("Handler"),
            "A",
            build_handler_run_impl_graph("A::run"),
        );
        cc.register_trait_method(
            "run",
            Some("Handler"),
            "B",
            build_handler_run_impl_graph("B::run"),
        );
        cc.find_all_graphs_for_tests();

        let mut graph = FunctionGraph::new("outer");
        let receiver_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "handler".to_string(),
                    ty: ValueType::Unknown,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::indirect("Handler", "run"),
                args: crate::model::call_args(vec![receiver_var]),
                result_ty: ValueType::Void,
            },
            true,
        );
        graph.set_return(graph.startblock, None);

        annotate(&graph);
        resolve_types(&graph);
        lower_indirect_calls(&mut graph, &cc);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);

        let ops = &result.graph.block(graph.startblock).operations;
        let post_input = &ops[1..];
        assert!(
            matches!(post_input[0].kind, OpKind::VtableMethodPtr { .. }),
            "expected VtableMethodPtr first, got {:?}",
            post_input[0].kind
        );
        assert!(
            matches!(post_input[1].kind, OpKind::Live),
            "expected Live second, got {:?}",
            post_input[1].kind
        );
        match &post_input[2].kind {
            OpKind::GuardValue { kind_char: 'i', .. } => {}
            other => panic!("expected GuardValue kind='i', got {other:?}"),
        }
        match &post_input[3].kind {
            OpKind::CallResidual {
                funcptr: CallFuncPtr::Value(_),
                indirect_targets: Some(t),
                ..
            } => assert_eq!(t.lst.len(), 2, "both impls should be candidates"),
            other => panic!(
                "expected CallResidual with runtime funcptr + indirect_targets, got {other:?}"
            ),
        }
        // jtransform.py handle_residual_call(..., may_call_jitcodes=True)
        // forces a trailing `-live-`.
        assert!(
            matches!(post_input[4].kind, OpKind::Live),
            "expected trailing Live, got {:?}",
            post_input[4].kind
        );
    }

    /// End-to-end smoke: after the rtyper-equivalent `lower_indirect_calls`
    /// pass + `Transformer::transform`, the `CallResidual.indirect_targets`
    /// payload carries exactly one `JitCodeHandle` per candidate impl
    /// (each shell allocated by `CallControl::get_jitcode`). The assembler
    /// later merges these handles into `Assembler.indirectcalltargets`
    /// (RPython `assembler.py:208-209`).
    #[test]
    fn indirectcalltargets_reach_call_residual_payload() {
        use crate::call::CallControl;
        use crate::translator::rtyper::legacy_annotator::annotate;
        use crate::translator::rtyper::legacy_resolve::resolve_types;
        use crate::translator::rtyper::rpbc::lower_indirect_calls;

        let mut cc = CallControl::new();
        cc.register_trait_method(
            "run",
            Some("Handler"),
            "A",
            build_handler_run_impl_graph("A::run"),
        );
        cc.register_trait_method(
            "run",
            Some("Handler"),
            "B",
            build_handler_run_impl_graph("B::run"),
        );
        cc.find_all_graphs_for_tests();

        let mut graph = FunctionGraph::new("outer");
        let receiver_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "handler".to_string(),
                    ty: ValueType::Unknown,
                    class_root: None,
                },
                true,
            )
            .unwrap();
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::indirect("Handler", "run"),
                args: crate::model::call_args(vec![receiver_var]),
                result_ty: ValueType::Void,
            },
            true,
        );
        graph.set_return(graph.startblock, None);

        annotate(&graph);
        resolve_types(&graph);
        lower_indirect_calls(&mut graph, &cc);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);

        let residual = result
            .graph
            .block(graph.startblock)
            .operations
            .iter()
            .find_map(|op| match &op.kind {
                OpKind::CallResidual {
                    indirect_targets, ..
                } => indirect_targets.clone(),
                _ => None,
            })
            .expect("residual call with indirect_targets");

        assert_eq!(residual.lst.len(), 2);
        // `IndirectCallTargets.lst` carries shell handles returned by
        // `CallControl::get_jitcode()`. RPython appends/indices jitcodes
        // only after `transform_graph_to_jitcode(...)` completes, so the
        // candidate handles must still be unindexed at this stage.
        assert!(
            residual.lst.iter().all(|h| h.try_index().is_none()),
            "indirect target shells should not have final all_jitcodes indices yet"
        );
    }

    // ── Kind matrix: `indirect_regular_call_{r,ir,irf}_{i,r,f,v}` ────
    //
    // RPython upstream: `test_jtransform.py` parameterization +
    // `test_jtransform.py indirect_regular_call_test`.  Each
    // test builds a `receiver.m(extras...)` site where `extras` covers
    // the arg kind signature (`r`, `ir`, `irf`) and `result_ty` covers
    // the result kind (`i`, `r`, `f`, `v`).  The emitted `CallResidual`
    // must split args into `(args_i, args_r, args_f)` by kind — with
    // the receiver always landing in `args_r` — and carry `result_kind`
    // matching the call's `result_ty`.  Receiver-in-args mirrors RPython
    // `rpbc.py MethodsPBCRepr.redispatch_call`.

    /// Runs the full rtyper-equivalent + jtransform pipeline for a
    /// `receiver.m(extras...)` dyn-Trait call and asserts the emitted
    /// op sequence is exactly
    /// `[VtableMethodPtr, Live, GuardValue{'i'}, CallResidual, Live]`,
    /// with the CallResidual's arg-kind distribution matching `expect`
    /// and `result_kind` matching `expect_res_kind`.  Two impls are
    /// registered so `CallKind::Regular` is selected.
    #[cfg(test)]
    fn check_indirect_regular_call_kind(
        extras: &[ValueType],
        result_ty: ValueType,
        expect: (usize, usize, usize),
        expect_res_kind: char,
    ) {
        use crate::call::CallControl;
        use crate::translator::rtyper::legacy_annotator::annotate;
        use crate::translator::rtyper::legacy_resolve::resolve_types;
        use crate::translator::rtyper::rpbc::lower_indirect_calls;

        let build_impl = |name: &str| {
            let mut g = FunctionGraph::new(name);
            g.push_op_var(
                g.startblock,
                OpKind::Input {
                    name: "self".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
            for (i, ty) in extras.iter().enumerate() {
                g.push_op_var(
                    g.startblock,
                    OpKind::Input {
                        name: format!("a{i}"),
                        ty: ty.clone(),
                        class_root: None,
                    },
                    true,
                )
                .unwrap();
            }
            g.set_return(g.startblock, None);
            g
        };

        // The indirect branch of `getcalldescr(op)` validates that the
        // caller's `result_type` matches the witness impl's declared
        // return type (`call.rs` indirect-arm signature check).  Stamp the
        // matching return type onto the impl graphs so the non-void
        // kind-matrix cases resolve without panicking.
        let return_str = match result_ty {
            ValueType::Int | ValueType::State => "i64",
            ValueType::Unsigned => "u64",
            ValueType::Ref(_) | ValueType::Str | ValueType::StringBuilder | ValueType::Unknown => {
                "String"
            }
            ValueType::Float => "f64",
            ValueType::SingleFloat => "f32",
            ValueType::Void => "",
            ValueType::Bool => "bool",
            ValueType::Int128 => "i128",
            ValueType::UInt128 => "u128",
        };
        let build_witness = |name: &str| {
            let g = build_impl(name);
            if return_str.is_empty() {
                g
            } else {
                g.with_return_type(return_str)
            }
        };
        let mut cc = CallControl::new();
        cc.register_trait_method("m", Some("T"), "A", build_witness("A::m"));
        cc.register_trait_method("m", Some("T"), "B", build_witness("B::m"));
        cc.find_all_graphs_for_tests();

        let mut graph = FunctionGraph::new("outer");
        let receiver_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "self".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let mut args_vars: Vec<crate::flowspace::model::Variable> = vec![receiver_var];
        for (i, ty) in extras.iter().enumerate() {
            args_vars.push(
                graph
                    .push_op_var(
                        graph.startblock,
                        OpKind::Input {
                            name: format!("a{i}"),
                            ty: ty.clone(),
                            class_root: None,
                        },
                        true,
                    )
                    .unwrap(),
            );
        }
        let has_result = !matches!(result_ty, ValueType::Void);
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::indirect("T", "m"),
                args: crate::model::call_args(args_vars),
                result_ty,
            },
            has_result,
        );
        graph.set_return(graph.startblock, None);

        annotate(&graph);
        resolve_types(&graph);
        lower_indirect_calls(&mut graph, &cc);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);

        let ops = &result.graph.block(graph.startblock).operations;
        let post_input: Vec<_> = ops
            .iter()
            .filter(|op| !matches!(&op.kind, OpKind::Input { .. }))
            .collect();

        assert!(
            matches!(post_input[0].kind, OpKind::VtableMethodPtr { .. }),
            "expected VtableMethodPtr first, got {:?}",
            post_input[0].kind,
        );
        assert!(
            matches!(post_input[1].kind, OpKind::Live),
            "expected Live second, got {:?}",
            post_input[1].kind,
        );
        assert!(
            matches!(
                post_input[2].kind,
                OpKind::GuardValue { kind_char: 'i', .. }
            ),
            "expected GuardValue kind_char='i', got {:?}",
            post_input[2].kind,
        );
        match &post_input[3].kind {
            OpKind::CallResidual {
                funcptr: CallFuncPtr::Value(_),
                args_i,
                args_r,
                args_f,
                result_kind,
                indirect_targets: Some(t),
                ..
            } => {
                assert_eq!(args_i.len(), expect.0, "args_i count");
                assert_eq!(args_r.len(), expect.1, "args_r count (receiver counted)");
                assert_eq!(args_f.len(), expect.2, "args_f count");
                assert_eq!(*result_kind, expect_res_kind, "result_kind");
                assert_eq!(t.lst.len(), 2, "both impls in family");
            }
            other => {
                panic!("expected CallResidual with Value funcptr + indirect_targets, got {other:?}")
            }
        }
        assert!(
            matches!(post_input[4].kind, OpKind::Live),
            "expected trailing Live (may_call_jitcodes=true), got {:?}",
            post_input[4].kind,
        );
    }

    #[test]
    fn indirect_regular_call_kinds() {
        let none: &[ValueType] = &[];
        let int_only: &[ValueType] = &[ValueType::Int];
        let int_float: &[ValueType] = &[ValueType::Int, ValueType::Float];
        let arg_sets: &[(&str, &[ValueType], (usize, usize, usize))] = &[
            ("r", none, (0, 1, 0)),
            ("ir", int_only, (1, 1, 0)),
            ("irf", int_float, (1, 1, 1)),
        ];
        let results = [
            ("i", ValueType::Int, 'i'),
            ("r", ValueType::Ref(None), 'r'),
            ("f", ValueType::Float, 'f'),
            ("v", ValueType::Void, 'v'),
        ];
        for (arg_name, extras, expect) in arg_sets {
            for (res_name, result_ty, kind) in &results {
                let name = format!("{arg_name}_{res_name}");
                let result_ty = result_ty.clone();
                let kind = *kind;
                let expect = *expect;
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    check_indirect_regular_call_kind(extras, result_ty, expect, kind);
                }));
                if let Err(payload) = result {
                    panic!("case {name}: {}", panic_payload_jt(&payload));
                }
            }
        }
    }

    fn panic_payload_jt(payload: &Box<dyn std::any::Any + Send>) -> String {
        if let Some(s) = payload.downcast_ref::<String>() {
            s.clone()
        } else if let Some(s) = payload.downcast_ref::<&str>() {
            (*s).to_string()
        } else {
            "assertion failed".to_string()
        }
    }

    // ── Kind matrix: `indirect_residual_call_{r,ir,irf}_{i,r,f,v}` ───
    //
    // RPython upstream: `test_jtransform.py indirect_residual_call_test`.
    // `handle_residual_indirect_call` is an alias for the regular
    // residual-call path (`jtransform.py`): no `int_guard_value` guard
    // and no `IndirectCallTargets` sidecar; only `[residual_call_*, -live-]`.
    // On the pyre side we additionally retain the `VtableMethodPtr` op
    // emitted by `lower_indirect_calls` — the rtyper-equivalent layer runs
    // unconditionally and provides the runtime funcptr `Variable` consumed
    // by the `CallResidual.funcptr` `CallFuncPtr::Value` operand.

    /// Same skeleton as `check_indirect_regular_call_kind` but drops
    /// `find_all_graphs_for_tests`, so `candidate_graphs` stays empty
    /// and `guess_call_kind(op)` falls through to `CallKind::Residual`
    /// via the `graphs_from(op)` call.py fall-through.
    /// Emit is `[VtableMethodPtr, CallResidual{indirect_targets: None},
    /// Live?]` — the trailing `-live-` appears only when the descriptor's
    /// `can_raise` is true, which is the default for non-elidable
    /// family calls.
    #[cfg(test)]
    fn check_indirect_residual_call_kind(
        extras: &[ValueType],
        result_ty: ValueType,
        expect: (usize, usize, usize),
        expect_res_kind: char,
    ) {
        use crate::call::CallControl;
        use crate::translator::rtyper::legacy_annotator::annotate;
        use crate::translator::rtyper::legacy_resolve::resolve_types;
        use crate::translator::rtyper::rpbc::lower_indirect_calls;

        let build_impl = |name: &str| {
            let mut g = FunctionGraph::new(name);
            g.push_op_var(
                g.startblock,
                OpKind::Input {
                    name: "self".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
            for (i, ty) in extras.iter().enumerate() {
                g.push_op_var(
                    g.startblock,
                    OpKind::Input {
                        name: format!("a{i}"),
                        ty: ty.clone(),
                        class_root: None,
                    },
                    true,
                )
                .unwrap();
            }
            g.set_return(g.startblock, None);
            g
        };

        let return_str = match result_ty {
            ValueType::Int | ValueType::State => "i64",
            ValueType::Unsigned => "u64",
            ValueType::Ref(_) | ValueType::Str | ValueType::StringBuilder | ValueType::Unknown => {
                "String"
            }
            ValueType::Float => "f64",
            ValueType::SingleFloat => "f32",
            ValueType::Void => "",
            ValueType::Bool => "bool",
            ValueType::Int128 => "i128",
            ValueType::UInt128 => "u128",
        };
        let build_witness = |name: &str| {
            let g = build_impl(name);
            if return_str.is_empty() {
                g
            } else {
                g.with_return_type(return_str)
            }
        };
        let mut cc = CallControl::new();
        cc.register_trait_method("m", Some("T"), "A", build_witness("A::m"));
        cc.register_trait_method("m", Some("T"), "B", build_witness("B::m"));
        // NOTE: intentionally *no* `find_all_graphs_for_tests` — that keeps
        // `candidate_graphs` empty so `guess_call_kind(op)` classifies
        // this call as `CallKind::Residual` via the call.py
        // `graphs_from(op) is None` fall-through.

        let mut graph = FunctionGraph::new("outer");
        let receiver_var = graph
            .push_op_var(
                graph.startblock,
                OpKind::Input {
                    name: "self".into(),
                    ty: ValueType::Ref(None),
                    class_root: None,
                },
                true,
            )
            .unwrap();
        let mut args_vars: Vec<crate::flowspace::model::Variable> = vec![receiver_var];
        for (i, ty) in extras.iter().enumerate() {
            args_vars.push(
                graph
                    .push_op_var(
                        graph.startblock,
                        OpKind::Input {
                            name: format!("a{i}"),
                            ty: ty.clone(),
                            class_root: None,
                        },
                        true,
                    )
                    .unwrap(),
            );
        }
        let has_result = !matches!(result_ty, ValueType::Void);
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::indirect("T", "m"),
                args: crate::model::call_args(args_vars),
                result_ty,
            },
            has_result,
        );
        graph.set_return(graph.startblock, None);

        annotate(&graph);
        resolve_types(&graph);
        lower_indirect_calls(&mut graph, &cc);

        let config = GraphTransformConfig::default();
        let mut transformer = Transformer::new(&config).with_callcontrol(&mut cc);
        let result = transformer.transform(&graph);

        let ops = &result.graph.block(graph.startblock).operations;
        let post_input: Vec<_> = ops
            .iter()
            .filter(|op| !matches!(&op.kind, OpKind::Input { .. }))
            .collect();

        assert!(
            matches!(post_input[0].kind, OpKind::VtableMethodPtr { .. }),
            "expected VtableMethodPtr first, got {:?}",
            post_input[0].kind,
        );
        // Residual path must NOT emit the [Live, GuardValue] prefix —
        // upstream `jtransform.py:536` aliases
        // `handle_residual_indirect_call = handle_residual_call`.
        assert!(
            !post_input
                .iter()
                .any(|op| matches!(op.kind, OpKind::GuardValue { .. })),
            "residual path must not emit int_guard_value, got ops: {:?}",
            post_input.iter().map(|op| &op.kind).collect::<Vec<_>>(),
        );
        match &post_input[1].kind {
            OpKind::CallResidual {
                funcptr: CallFuncPtr::Value(_),
                args_i,
                args_r,
                args_f,
                result_kind,
                indirect_targets: None,
                ..
            } => {
                assert_eq!(args_i.len(), expect.0, "args_i count");
                assert_eq!(args_r.len(), expect.1, "args_r count (receiver counted)");
                assert_eq!(args_f.len(), expect.2, "args_f count");
                assert_eq!(*result_kind, expect_res_kind, "result_kind");
            }
            other => panic!(
                "expected CallResidual with Value funcptr + indirect_targets=None, got {other:?}"
            ),
        }
    }

    #[test]
    fn indirect_residual_call_kinds() {
        let none: &[ValueType] = &[];
        let int_only: &[ValueType] = &[ValueType::Int];
        let int_float: &[ValueType] = &[ValueType::Int, ValueType::Float];
        let arg_sets: &[(&str, &[ValueType], (usize, usize, usize))] = &[
            ("r", none, (0, 1, 0)),
            ("ir", int_only, (1, 1, 0)),
            ("irf", int_float, (1, 1, 1)),
        ];
        let results = [
            ("i", ValueType::Int, 'i'),
            ("r", ValueType::Ref(None), 'r'),
            ("f", ValueType::Float, 'f'),
            ("v", ValueType::Void, 'v'),
        ];
        for (arg_name, extras, expect) in arg_sets {
            for (res_name, result_ty, kind) in &results {
                let name = format!("{arg_name}_{res_name}");
                let result_ty = result_ty.clone();
                let kind = *kind;
                let expect = *expect;
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    check_indirect_residual_call_kind(extras, result_ty, expect, kind);
                }));
                if let Err(payload) = result {
                    panic!("case {name}: {}", panic_payload_jt(&payload));
                }
            }
        }
    }

    /// `rpython/jit/codewriter/jtransform.py:599-606` — when a
    /// `hint(arg, promote=True, promote_string=True)` carries both
    /// flags, the rewrite drops one based on whether the arg's
    /// `concretetype` is `Ptr(STR)`.  Pyre's `value_kind` is too
    /// coarse to make that distinction (every pointer maps to `'r'`),
    /// so `PromoteOrString` defaults to the plain `<kind>_guard_value`
    /// path — `ref_guard_value` is safe for every Ref, including
    /// non-string pointers.  Users who need the value-equality
    /// `str_guard_value` shape invoke `hint_promote_string(x)`
    /// explicitly.
    #[test]
    fn transform_graph_promote_or_string_picks_ref_guard_value_for_ref_arg() {
        let mut graph = FunctionGraph::new("demo");
        let v_var = graph.alloc_value_var();
        graph.push_inputarg_var(graph.startblock, v_var.clone());
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::function_path(["hint_promote_or_string"]),
                args: crate::model::call_args(vec![v_var]),
                result_ty: ValueType::Ref(None),
            },
            false,
        );
        graph.set_return(graph.startblock, None);

        let result = transform_graph(&graph, &GraphTransformConfig::default());
        let ops = &result.graph.block(graph.startblock).operations;
        assert_eq!(ops.len(), 2);
        assert!(matches!(ops[0].kind, OpKind::Live));
        match &ops[1].kind {
            OpKind::GuardValue { kind_char, .. } => {
                assert_eq!(
                    *kind_char, 'r',
                    "Ref arg must default to ref_guard_value (no Ptr(STR) info)"
                );
            }
            other => panic!("expected GuardValue, got {other:?}"),
        }
    }

    #[test]
    fn transform_graph_promote_or_string_picks_int_guard_value_for_int_arg() {
        let mut graph = FunctionGraph::new("demo");
        let v_var = graph.alloc_value_var();
        graph.push_inputarg_var(graph.startblock, v_var.clone());
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::function_path(["hint_promote_or_string"]),
                args: crate::model::call_args(vec![v_var.clone()]),
                result_ty: ValueType::Int,
            },
            false,
        );
        graph.set_return(graph.startblock, None);

        // value_kind defaults to 'r' without an entry in type_state;
        // seed `v` as `Signed` so the dual-hint arm sees an Int arg
        // and routes through the plain `<kind>_guard_value` path
        // instead of the str_guard_value helper chain.
        FunctionGraph::set_concretetype_of_inline(&v_var, ConcreteType::Signed);
        let config = GraphTransformConfig::default();
        let result = Transformer::new(&config).transform(&graph);
        let ops = &result.graph.block(graph.startblock).operations;
        assert!(matches!(ops[0].kind, OpKind::Live));
        match &ops[1].kind {
            OpKind::GuardValue { kind_char, .. } => {
                assert_eq!(
                    *kind_char, 'i',
                    "Int arg must route through the int_guard_value path"
                );
            }
            other => panic!("expected GuardValue, got {other:?}"),
        }
    }

    /// `promote_string` lowers a `W_UnicodeObject` ref through the shared
    /// `<kind>_guard_value` family: pyre has no `Ptr(rstr.STR)` to
    /// value-compare, so the ref operand collapses to `r_guard_value`
    /// (`rpython/jit/codewriter/jtransform.py:615-631`).
    #[test]
    fn transform_graph_promote_string_emits_ref_guard_value() {
        let mut graph = FunctionGraph::new("demo");
        let v_var = graph.alloc_value_var();
        graph.push_inputarg_var(graph.startblock, v_var.clone());
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::function_path(["hint_promote_string"]),
                args: crate::model::call_args(vec![v_var]),
                result_ty: ValueType::Ref(None),
            },
            false,
        );
        graph.set_return(graph.startblock, None);

        let result = transform_graph(&graph, &GraphTransformConfig::default());
        let ops = &result.graph.block(graph.startblock).operations;
        assert_eq!(ops.len(), 2);
        assert!(matches!(ops[0].kind, OpKind::Live));
        match &ops[1].kind {
            OpKind::GuardValue { kind_char, .. } => {
                assert_eq!(
                    *kind_char, 'r',
                    "string promote on a ref must emit r_guard_value"
                );
            }
            other => panic!("expected GuardValue, got {other:?}"),
        }
    }

    /// `promote_unicode` shares the `PromoteString` lowering — the
    /// `rstr.UNICODE` value-equality guard has no `W_UnicodeObject`
    /// counterpart, so the ref operand emits `r_guard_value`
    /// (`rpython/jit/codewriter/jtransform.py:632-648`).
    #[test]
    fn transform_graph_promote_unicode_emits_ref_guard_value() {
        let mut graph = FunctionGraph::new("demo");
        let v_var = graph.alloc_value_var();
        graph.push_inputarg_var(graph.startblock, v_var.clone());
        graph.push_op_var(
            graph.startblock,
            OpKind::Call {
                target: CallTarget::function_path(["hint_promote_unicode"]),
                args: crate::model::call_args(vec![v_var]),
                result_ty: ValueType::Ref(None),
            },
            false,
        );
        graph.set_return(graph.startblock, None);

        let result = transform_graph(&graph, &GraphTransformConfig::default());
        let ops = &result.graph.block(graph.startblock).operations;
        assert_eq!(ops.len(), 2);
        assert!(matches!(ops[0].kind, OpKind::Live));
        match &ops[1].kind {
            OpKind::GuardValue { kind_char, .. } => {
                assert_eq!(
                    *kind_char, 'r',
                    "unicode promote on a ref must emit r_guard_value"
                );
            }
            other => panic!("expected GuardValue, got {other:?}"),
        }
    }

    fn rust_vec_var(
        graph: &mut FunctionGraph,
        kind: majit_ir::rvec::VecItemKind,
    ) -> crate::flowspace::model::Variable {
        use crate::translator::rtyper::lltypesystem::lltype::LowLevelType;
        let item = match kind {
            majit_ir::rvec::VecItemKind::Int => LowLevelType::Signed,
            majit_ir::rvec::VecItemKind::Float => LowLevelType::Float,
            majit_ir::rvec::VecItemKind::Ref => {
                crate::translator::rtyper::lltypesystem::lltype::GCREF.clone()
            }
        };
        let v = graph.alloc_value_var_with_type(ConcreteType::Signed);
        v.set_concretetype(Some(crate::translator::rtyper::rrustvec::rust_vec_lltype(
            &item,
        )));
        v
    }

    fn const_int_of(ops: &[SpaceOperation], var: &crate::flowspace::model::Variable) -> i64 {
        ops.iter()
            .find_map(|op| match (&op.result, &op.kind) {
                (Some(result), OpKind::ConstInt(value)) if result == var => Some(*value),
                _ => None,
            })
            .unwrap_or_else(|| panic!("{var:?} is not a ConstInt result"))
    }

    /// `list.len` / `list.getitem` / `list.setitem` on a `RustVec` header are
    /// `raw_load` of the header words at the `majit_ir::rvec` offsets and a
    /// `nolength` raw item access; a reference item crosses as a word.
    #[test]
    fn handle_list_call_rust_vec_accesses_lower_to_raw_ops() {
        use majit_ir::rvec::{VEC_LEN_WORD, VEC_PTR_WORD, VecItemKind, vec_word_offset};
        let word = crate::layout::target_word_size();
        for kind in VecItemKind::ALL {
            let mut graph = FunctionGraph::new("raw_list");
            let l = rust_vec_var(&mut graph, kind);
            let index = graph.alloc_value_var_with_type(ConcreteType::Signed);
            let item_ct = match kind {
                VecItemKind::Int => ConcreteType::Signed,
                VecItemKind::Ref => ConcreteType::GcRef,
                VecItemKind::Float => ConcreteType::Float,
            };
            let item = graph.alloc_value_var_with_type(item_ct);
            let result = graph.alloc_value_var_with_type(ConcreteType::Signed);

            let config = GraphTransformConfig::default();
            let mut transformer = Transformer::new(&config);
            let op = SpaceOperation {
                result: Some(result.clone()),
                kind: OpKind::ConstInt(0),
            };
            let Some(RewriteResult::Replace(ops)) = transformer._handle_list_call(
                "list.len",
                &op,
                std::slice::from_ref(&l),
                &mut graph,
                "raw_list",
            ) else {
                panic!("list.len must lower");
            };
            let [.., last] = ops.as_slice() else {
                unreachable!()
            };
            let OpKind::RawLoad {
                base,
                offset,
                item_ty,
                itemsize,
                ..
            } = &last.kind
            else {
                panic!("expected RawLoad, got {:?}", last.kind);
            };
            assert_eq!(base, &l);
            assert_eq!(
                const_int_of(&ops, offset),
                vec_word_offset(VEC_LEN_WORD, word) as i64
            );
            assert_eq!(*item_ty, ValueType::Int);
            assert_eq!(*itemsize, word);
            assert_eq!(last.result.as_ref(), Some(&result));

            let got = graph.alloc_value_var_with_type(item_ct);
            let op = SpaceOperation {
                result: Some(got.clone()),
                kind: OpKind::ConstInt(0),
            };
            let Some(RewriteResult::Replace(ops)) = transformer._handle_list_call(
                "list.getitem",
                &op,
                &[l.clone(), index.clone()],
                &mut graph,
                "raw_list",
            ) else {
                panic!("list.getitem must lower");
            };
            let body: Vec<_> = ops
                .iter()
                .filter(|op| !matches!(op.kind, OpKind::ConstInt(_)))
                .collect();
            let OpKind::RawLoad { base, offset, .. } = &body[0].kind else {
                panic!("expected the buffer RawLoad, got {:?}", body[0].kind);
            };
            assert_eq!(base, &l);
            assert_eq!(
                const_int_of(&ops, offset),
                vec_word_offset(VEC_PTR_WORD, word) as i64
            );
            let items = body[0].result.clone().unwrap();
            let OpKind::ArrayRead {
                base,
                index: read_index,
                item_ty,
                nolength,
                pure,
                ..
            } = &body[1].kind
            else {
                panic!("expected ArrayRead, got {:?}", body[1].kind);
            };
            assert_eq!(base, &items);
            assert_eq!(read_index, &index);
            assert!(*nolength && !*pure);
            match kind {
                VecItemKind::Float => assert_eq!(*item_ty, ValueType::Float),
                _ => assert_eq!(*item_ty, ValueType::Int),
            }
            if kind == VecItemKind::Ref {
                let OpKind::UnaryOp { op, operand, .. } = &body[2].kind else {
                    panic!("expected cast_int_to_ptr, got {:?}", body[2].kind);
                };
                assert_eq!(op, "cast_int_to_ptr");
                assert_eq!(Some(operand), body[1].result.as_ref());
                assert_eq!(body[2].result.as_ref(), Some(&got));
            } else {
                assert_eq!(body.len(), 2);
                assert_eq!(body[1].result.as_ref(), Some(&got));
            }

            let op = SpaceOperation {
                result: None,
                kind: OpKind::ConstInt(0),
            };
            let Some(RewriteResult::Replace(ops)) = transformer._handle_list_call(
                "list.setitem",
                &op,
                &[l.clone(), index.clone(), item.clone()],
                &mut graph,
                "raw_list",
            ) else {
                panic!("list.setitem must lower");
            };
            let body: Vec<_> = ops
                .iter()
                .filter(|op| !matches!(op.kind, OpKind::ConstInt(_)))
                .collect();
            let write = body.last().unwrap();
            let OpKind::ArrayWrite {
                value, nolength, ..
            } = &write.kind
            else {
                panic!("expected ArrayWrite, got {:?}", write.kind);
            };
            assert!(*nolength);
            let crate::model::LinkArg::Value(value) = value else {
                panic!("the stored item is a Variable");
            };
            if kind == VecItemKind::Ref {
                let OpKind::UnaryOp { op, operand, .. } = &body[1].kind else {
                    panic!("expected cast_ptr_to_int, got {:?}", body[1].kind);
                };
                assert_eq!(op, "cast_ptr_to_int");
                assert_eq!(operand, &item);
                assert_eq!(body[1].result.as_ref(), Some(value));
            } else {
                assert_eq!(value, &item);
            }
        }
    }

    /// `newlist(0)` / `newlist_hint(n)` on a `RustVec` result allocate the
    /// header through `raw_malloc_varsize_char` and store its three words;
    /// the hinted form allocates the buffer through `vec_buf_alloc`.
    #[test]
    fn handle_list_call_rust_vec_constructors_store_the_header() {
        use majit_ir::rvec::{
            VEC_BUF_ALLOC, VEC_CAP_WORD, VEC_HEADER_MALLOC, VEC_HEADER_WORDS, VEC_LEN_WORD,
            VEC_PTR_WORD, VecItemKind, vec_word_offset,
        };
        let word = crate::layout::target_word_size();
        let call_path = |op: &SpaceOperation| match &op.kind {
            OpKind::Call {
                target: CallTarget::FunctionPath { segments, .. },
                ..
            } => Some(segments.join("::")),
            _ => None,
        };
        for kind in VecItemKind::ALL {
            let (itemsize, itemalign) = kind.size_align(word);
            for hinted in [false, true] {
                let mut graph = FunctionGraph::new("raw_list_new");
                let header = rust_vec_var(&mut graph, kind);
                let hint = graph.alloc_value_var_with_type(ConcreteType::Signed);
                let (oopspec, args) = if hinted {
                    ("newlist_hint", vec![hint.clone()])
                } else {
                    ("newlist", vec![])
                };
                let ops = {
                    let config = GraphTransformConfig::default();
                    let mut transformer = Transformer::new(&config);
                    let op = SpaceOperation {
                        result: Some(header.clone()),
                        kind: OpKind::ConstInt(0),
                    };
                    let Some(RewriteResult::Replace(ops)) =
                        transformer._handle_list_call(oopspec, &op, &args, &mut graph, "raw_list")
                    else {
                        panic!("{oopspec} must lower");
                    };
                    ops
                };
                let malloc = ops
                    .iter()
                    .find(|op| call_path(op).as_deref() == Some(VEC_HEADER_MALLOC))
                    .expect("header malloc");
                assert_eq!(malloc.result.as_ref(), Some(&header));
                let OpKind::Call { args: margs, .. } = &malloc.kind else {
                    unreachable!()
                };
                let [crate::model::LinkArg::Value(size)] = margs.as_slice() else {
                    panic!("raw_malloc_varsize_char takes the size");
                };
                assert_eq!(const_int_of(&ops, size), (VEC_HEADER_WORDS * word) as i64);
                let buf_alloc = ops
                    .iter()
                    .find(|op| call_path(op).as_deref() == Some(VEC_BUF_ALLOC));
                assert_eq!(buf_alloc.is_some(), hinted);
                let stores: std::collections::BTreeMap<i64, crate::flowspace::model::Variable> =
                    ops.iter()
                        .filter_map(|op| match &op.kind {
                            OpKind::RawStore {
                                base,
                                offset,
                                value,
                                ..
                            } if base == &header => {
                                Some((const_int_of(&ops, offset), value.clone()))
                            }
                            _ => None,
                        })
                        .collect();
                assert_eq!(stores.len(), 3);
                let at = |index| &stores[&(vec_word_offset(index, word) as i64)];
                assert_eq!(const_int_of(&ops, at(VEC_LEN_WORD)), 0);
                if let Some(buf_alloc) = buf_alloc {
                    assert_eq!(at(VEC_PTR_WORD), buf_alloc.result.as_ref().unwrap());
                    assert_eq!(at(VEC_CAP_WORD), &hint);
                    let OpKind::Call { args: bargs, .. } = &buf_alloc.kind else {
                        unreachable!()
                    };
                    let [
                        crate::model::LinkArg::Value(n),
                        crate::model::LinkArg::Value(size),
                        crate::model::LinkArg::Value(align),
                    ] = bargs.as_slice()
                    else {
                        panic!("vec_buf_alloc takes (allocated, itemsize, align)");
                    };
                    assert_eq!(n, &hint);
                    assert_eq!(const_int_of(&ops, size), itemsize as i64);
                    assert_eq!(const_int_of(&ops, align), itemalign as i64);
                } else {
                    assert_eq!(const_int_of(&ops, at(VEC_PTR_WORD)), itemalign as i64);
                    assert_eq!(const_int_of(&ops, at(VEC_CAP_WORD)), 0);
                }
            }
        }
    }

    /// `do_resizable_newlist`: `newlist(length)` stores `length` in both the
    /// length and the capacity words and allocates that many slots through
    /// `vec_buf_alloc`.
    #[test]
    fn handle_list_call_rust_vec_newlist_length_stores_the_length() {
        use majit_ir::rvec::{
            VEC_BUF_ALLOC, VEC_CAP_WORD, VEC_LEN_WORD, VEC_PTR_WORD, VecItemKind, vec_word_offset,
        };
        let word = crate::layout::target_word_size();
        for kind in VecItemKind::ALL {
            let (itemsize, itemalign) = kind.size_align(word);
            let mut graph = FunctionGraph::new("raw_list_newlist");
            let header = rust_vec_var(&mut graph, kind);
            let length = graph.alloc_value_var_with_type(ConcreteType::Signed);
            let ops = {
                let config = GraphTransformConfig::default();
                let mut transformer = Transformer::new(&config);
                let op = SpaceOperation {
                    result: Some(header.clone()),
                    kind: OpKind::ConstInt(0),
                };
                let Some(RewriteResult::Replace(ops)) = transformer._handle_list_call(
                    "newlist",
                    &op,
                    std::slice::from_ref(&length),
                    &mut graph,
                    "raw_list_newlist",
                ) else {
                    panic!("newlist(length) must lower");
                };
                ops
            };
            let call_path = |op: &SpaceOperation| match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } => Some(segments.join("::")),
                _ => None,
            };
            let buf_alloc = ops
                .iter()
                .find(|op| call_path(op).as_deref() == Some(VEC_BUF_ALLOC))
                .expect("vec_buf_alloc");
            let OpKind::Call { args: bargs, .. } = &buf_alloc.kind else {
                unreachable!()
            };
            let [
                crate::model::LinkArg::Value(n),
                crate::model::LinkArg::Value(size),
                crate::model::LinkArg::Value(align),
            ] = bargs.as_slice()
            else {
                panic!("vec_buf_alloc takes (allocated, itemsize, align)");
            };
            assert_eq!(n, &length);
            assert_eq!(const_int_of(&ops, size), itemsize as i64);
            assert_eq!(const_int_of(&ops, align), itemalign as i64);
            let stores: std::collections::BTreeMap<i64, crate::flowspace::model::Variable> = ops
                .iter()
                .filter_map(|op| match &op.kind {
                    OpKind::RawStore {
                        base,
                        offset,
                        value,
                        ..
                    } if base == &header => Some((const_int_of(&ops, offset), value.clone())),
                    _ => None,
                })
                .collect();
            let at = |index| &stores[&(vec_word_offset(index, word) as i64)];
            assert_eq!(at(VEC_PTR_WORD), buf_alloc.result.as_ref().unwrap());
            assert_eq!(at(VEC_LEN_WORD), &length);
            assert_eq!(at(VEC_CAP_WORD), &length);
            assert!(
                !ops.iter().any(|op| {
                    matches!(
                        op.kind,
                        OpKind::NewListClear { .. } | OpKind::NewArrayClear { .. }
                    )
                }),
                "a raw header must not take the GC newlist arm"
            );
        }
    }

    /// `do_resizable_newlist_clear`: `newlist_clear(count)` on a raw header
    /// calls the zero-filling allocator and stores `count` as length and
    /// capacity. It does not emit the GC `newlist_clear` op.
    #[test]
    fn handle_list_call_rust_vec_newlist_clear_zero_fills() {
        use majit_ir::rvec::{
            VEC_BUF_ALLOC_CLEAR, VEC_CAP_WORD, VEC_LEN_WORD, VEC_PTR_WORD, VecItemKind,
            vec_word_offset,
        };
        let word = crate::layout::target_word_size();
        for kind in VecItemKind::ALL {
            let mut graph = FunctionGraph::new("raw_list_newlist_clear");
            let header = rust_vec_var(&mut graph, kind);
            let count = graph.alloc_value_var_with_type(ConcreteType::Signed);
            let ops = {
                let config = GraphTransformConfig::default();
                let mut transformer = Transformer::new(&config);
                let op = SpaceOperation {
                    result: Some(header.clone()),
                    kind: OpKind::ConstInt(0),
                };
                let Some(RewriteResult::Replace(ops)) = transformer._handle_list_call(
                    "newlist_clear",
                    &op,
                    std::slice::from_ref(&count),
                    &mut graph,
                    "raw_list_newlist_clear",
                ) else {
                    panic!("newlist_clear(count) must lower on a raw header");
                };
                ops
            };
            let call_path = |op: &SpaceOperation| match &op.kind {
                OpKind::Call {
                    target: CallTarget::FunctionPath { segments, .. },
                    ..
                } => Some(segments.join("::")),
                _ => None,
            };
            let buf_alloc = ops
                .iter()
                .find(|op| call_path(op).as_deref() == Some(VEC_BUF_ALLOC_CLEAR))
                .expect("vec_buf_alloc_clear");
            let OpKind::Call { args: bargs, .. } = &buf_alloc.kind else {
                unreachable!()
            };
            let [crate::model::LinkArg::Value(n), _, _] = bargs.as_slice() else {
                panic!("vec_buf_alloc_clear takes (allocated, itemsize, align)");
            };
            assert_eq!(n, &count);
            assert!(
                !ops.iter()
                    .any(|op| call_path(op).as_deref() == Some(majit_ir::rvec::VEC_BUF_ALLOC))
            );
            let stores: std::collections::BTreeMap<i64, crate::flowspace::model::Variable> = ops
                .iter()
                .filter_map(|op| match &op.kind {
                    OpKind::RawStore {
                        base,
                        offset,
                        value,
                        ..
                    } if base == &header => Some((const_int_of(&ops, offset), value.clone())),
                    _ => None,
                })
                .collect();
            let at = |index| &stores[&(vec_word_offset(index, word) as i64)];
            assert_eq!(at(VEC_PTR_WORD), buf_alloc.result.as_ref().unwrap());
            assert_eq!(at(VEC_LEN_WORD), &count);
            assert_eq!(at(VEC_CAP_WORD), &count);
            assert!(
                !ops.iter().any(|op| {
                    matches!(
                        op.kind,
                        OpKind::NewListClear { .. } | OpKind::NewArrayClear { .. }
                    )
                }),
                "a raw header must not take the GC newlist_clear arm"
            );
        }
    }

    /// `list.int_len(l)` lowers to a single `getfield_gc_i(l,
    /// int_items.len)` (`do_resizable_list_len`).
    #[test]
    fn handle_list_call_int_len_lowers_to_getfield_len() {
        let config = GraphTransformConfig::default();
        let mut graph = FunctionGraph::new("list_int_len");
        let l = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let result = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let op = SpaceOperation {
            result: Some(result.clone()),
            kind: OpKind::ConstInt(0),
        };
        let mut transformer = Transformer::new(&config);
        let rewrite = transformer
            ._handle_list_call(
                "list.int_len",
                &op,
                std::slice::from_ref(&l),
                &mut graph,
                "list_int_len",
            )
            .expect("list.int_len must lower");
        let RewriteResult::Replace(ops) = rewrite else {
            panic!("expected Replace");
        };
        assert_eq!(ops.len(), 1);
        match &ops[0].kind {
            OpKind::FieldRead {
                base,
                field,
                ty,
                pure,
            } => {
                assert_eq!(base, &l);
                assert_eq!(field.name, "int_items.len");
                assert_eq!(field.owner_root.as_deref(), Some("W_ListObject"));
                assert!(matches!(ty, ValueType::Int));
                assert!(!pure);
            }
            other => panic!("expected FieldRead, got {other:?}"),
        }
        assert_eq!(ops[0].result, Some(result));
    }

    /// Fallback arm: a `newlist_clear` result with no recoverable list
    /// layout — a generic `OBJECTPTR` (`Ptr(GcStruct("object"))`) or a
    /// missing concretetype — is neither the `"list"` header struct nor a
    /// typed items array.  The allocation is still a fixed list of refs,
    /// so the arm emits `new_array_clear` with the `GcArray(OBJECTPTR)`
    /// identity `cpu.arraydescrof` uses for `wrappeditems`.  An
    /// identity-less descr mints `type_id = 0`.  The recovered-shape
    /// arms are covered by
    /// `handle_list_call_newlist_clear_resized_lowers_to_newlist_clear` and
    /// `handle_list_call_newlist_clear_fixed_recovers_int_item_ty`.
    #[test]
    fn handle_list_call_newlist_clear_untyped_result_falls_back_to_ref_array() {
        let config = GraphTransformConfig::default();
        let mut graph = FunctionGraph::new("newlist_clear");
        let count = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let result = graph.alloc_value_var_with_type(ConcreteType::GcRef);
        let op = SpaceOperation {
            result: Some(result.clone()),
            kind: OpKind::ConstInt(0),
        };
        let mut transformer = Transformer::new(&config);
        let rewrite = transformer
            ._handle_list_call(
                "newlist_clear",
                &op,
                std::slice::from_ref(&count),
                &mut graph,
                "newlist_clear",
            )
            .expect("newlist_clear must lower");
        let RewriteResult::Replace(ops) = rewrite else {
            panic!("expected Replace");
        };
        assert_eq!(ops.len(), 1);
        match &ops[0].kind {
            OpKind::NewArrayClear {
                length,
                item_ty,
                array_type_id,
            } => {
                assert_eq!(length, &count);
                assert!(matches!(item_ty, ValueType::Ref(None)));
                assert_eq!(
                    array_type_id.as_deref(),
                    Some(crate::front::mir::OBJECT_REF_GCARRAY_TYPE_ID),
                    "untyped newlist_clear of refs names the GcArray(OBJECTPTR) identity"
                );
            }
            other => panic!("expected NewArrayClear, got {other:?}"),
        }
        assert_eq!(ops[0].result, Some(result));
    }

    /// C1 fork, resized layout: a result typed
    /// `Ptr(GcStruct("list", {length, items: Ptr(GcArray(Signed))}))` — the
    /// resized `ListRepr` shape (`do_resizable_newlist_clear`,
    /// jtransform.py) — lowers to `NewListClear` (the struct-header
    /// compound op) with `item_ty` recovered from the items array element
    /// (`Signed` → `Int`), NOT the pre-fork bare `new_array_clear`.
    #[test]
    fn handle_list_call_newlist_clear_resized_lowers_to_newlist_clear() {
        use crate::translator::rtyper::lltypesystem::lltype::{
            Array, LowLevelType, Ptr, PtrTarget, Struct,
        };
        use crate::translator::rtyper::rtyper::variable_with_lltype;

        // upstream `GcStruct("list", ("length", Signed), ("items",
        // Ptr(GcArray(ITEM))))` with ITEM = Signed (an int-element list).
        let items_ptr = LowLevelType::Ptr(Box::new(Ptr {
            TO: PtrTarget::Array(Array::gc(LowLevelType::Signed)),
        }));
        let list_struct = Struct::gc(
            "list",
            vec![
                ("length".to_string(), LowLevelType::Signed),
                ("items".to_string(), items_ptr),
            ],
        );
        let list_ptr = LowLevelType::Ptr(Box::new(Ptr {
            TO: PtrTarget::Struct(list_struct),
        }));

        let config = GraphTransformConfig::default();
        let mut graph = FunctionGraph::new("newlist_clear_resized");
        let count = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let result = variable_with_lltype("l", list_ptr);
        let op = SpaceOperation {
            result: Some(result.clone()),
            kind: OpKind::ConstInt(0),
        };
        let mut transformer = Transformer::new(&config);
        let rewrite = transformer
            ._handle_list_call(
                "newlist_clear",
                &op,
                std::slice::from_ref(&count),
                &mut graph,
                "newlist_clear_resized",
            )
            .expect("newlist_clear must lower");
        let RewriteResult::Replace(ops) = rewrite else {
            panic!("expected Replace");
        };
        assert_eq!(ops.len(), 1);
        match &ops[0].kind {
            OpKind::NewListClear {
                length,
                item_ty,
                array_type_id,
            } => {
                assert_eq!(length, &count);
                assert!(
                    matches!(item_ty, ValueType::Int),
                    "int-element list items array must recover ValueType::Int, got {item_ty:?}"
                );
                assert_eq!(array_type_id, &None);
            }
            other => panic!("expected NewListClear, got {other:?}"),
        }
        assert_eq!(ops[0].result, Some(result));
    }

    /// C1 fork, fixed layout: a result typed `Ptr(GcArray(Signed))` — the
    /// fixed `FixedSizeListRepr` shape (`do_fixed_newlist_clear`,
    /// jtransform.py) — lowers to `NewArrayClear` with `item_ty`
    /// recovered from the array element (`Signed` → `Int`), proving the C1
    /// element-type recovery: the pre-fork arm hardcoded `Ref(None)`, which
    /// would GC-trace int slots as pointers.
    #[test]
    fn handle_list_call_newlist_clear_fixed_recovers_int_item_ty() {
        use crate::translator::rtyper::lltypesystem::lltype::{
            Array, LowLevelType, Ptr, PtrTarget,
        };
        use crate::translator::rtyper::rtyper::variable_with_lltype;

        let array_ptr = LowLevelType::Ptr(Box::new(Ptr {
            TO: PtrTarget::Array(Array::gc(LowLevelType::Signed)),
        }));

        let config = GraphTransformConfig::default();
        let mut graph = FunctionGraph::new("newlist_clear_fixed");
        let count = graph.alloc_value_var_with_type(ConcreteType::Signed);
        let result = variable_with_lltype("a", array_ptr);
        let op = SpaceOperation {
            result: Some(result.clone()),
            kind: OpKind::ConstInt(0),
        };
        let mut transformer = Transformer::new(&config);
        let rewrite = transformer
            ._handle_list_call(
                "newlist_clear",
                &op,
                std::slice::from_ref(&count),
                &mut graph,
                "newlist_clear_fixed",
            )
            .expect("newlist_clear must lower");
        let RewriteResult::Replace(ops) = rewrite else {
            panic!("expected Replace");
        };
        assert_eq!(ops.len(), 1);
        match &ops[0].kind {
            OpKind::NewArrayClear {
                length,
                item_ty,
                array_type_id,
            } => {
                assert_eq!(length, &count);
                assert!(
                    matches!(item_ty, ValueType::Int),
                    "int-element fixed array must recover ValueType::Int (NOT Ref(None)), \
                     got {item_ty:?}"
                );
                assert_eq!(array_type_id, &None);
            }
            other => panic!("expected NewArrayClear, got {other:?}"),
        }
        assert_eq!(ops[0].result, Some(result));
    }

